public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(AVADefaultCoilDiameterTable, Code):
            this.Relation = '';
            break;

        case fieldNum(AVADefaultCoilDiameterTable, Relation):
            if (this.Code == TableGroupAll::All)
            {
                this.Relation = ''; // clean AccountRealtion entry by all, normaly not needed as reseon of validateField method
            }
            break;
    }
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = super(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(AVADefaultCoilDiameterTable, Relation):
            if (ret && this.Code == TableGroupAll::All)
            {
                ret = checkFailed(strFmt("@NDX:MustBlankField", fieldId2pname(tableNum(AVADefaultCoilDiameterTable), fieldNum(AVADefaultCoilDiameterTable, Relation))));
            }
            break;
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(ret)
    {
        if (this.Code == TableGroupAll::All && this.Relation)
        {
            ret = checkFailed(strFmt("@NDX:MustBlankField", fieldId2pname(tableNum(AVADefaultCoilDiameterTable), fieldNum(AVADefaultCoilDiameterTable, Relation))));
        }

        if (this.Code != TableGroupAll::All && !this.Relation)
        {
            ret = checkFailed(strFmt("@SYS304397", fieldId2pname(tableNum(AVADefaultCoilDiameterTable), fieldNum(AVADefaultCoilDiameterTable, Relation))));
        }
    }

    return ret;
}

static public AVADefaultCoilDiameterTable find(AVADefaultCoilDiameterCode       _Code,
                                               AVADefaultCoilDiameterRelation   _Relation   = '',
                                               boolean                          _forUpdate  = false)
{
    AVADefaultCoilDiameterTable  defaultCoilDiameterTable;

    if (_forUpdate)
    {
        defaultCoilDiameterTable.selectForUpdate(_forUpdate);
    }

    select firstOnly defaultCoilDiameterTable
        where defaultCoilDiameterTable.Code       == _Code
           && defaultCoilDiameterTable.Relation   == _Relation;

    return defaultCoilDiameterTable;
}

static public AVADefaultCoilDiameterTable search(ItemId                     _itemId         = '',
                                                 NDXTRUMPFCharacteristicID  _coilMaterialId = '',
                                                 boolean                    _forUpdate      = false)
{
    AVADefaultCoilDiameterTable      defaultCoilDiameterTable;


    defaultCoilDiameterTable = AVADefaultCoilDiameterTable::find(TableGroupAll::Table,
                                                                 _ItemId,
                                                                 _forUpdate);
    if (!defaultCoilDiameterTable)
    {

        defaultCoilDiameterTable = AVADefaultCoilDiameterTable::find(TableGroupAll::GroupId,
                                                                     _CoilMaterialId,
                                                                     _forUpdate);
    }


    if (!defaultCoilDiameterTable)
    {
        defaultCoilDiameterTable = AVADefaultCoilDiameterTable::find(TableGroupAll::All,
                                                                     '',
                                                                     _forUpdate);
    }

    return defaultCoilDiameterTable;
}
